<?php require __DIR__.'/includes/session.php'; require __DIR__.'/includes/db.php'; $uid=(int)$_SESSION['user_id'];$st=mysqli_prepare($conn,"SELECT c.quantity,p.name,p.price FROM cart c JOIN products p ON c.product_id=p.id WHERE c.user_id=?");mysqli_stmt_bind_param($st,'i',$uid);mysqli_stmt_execute($st);$res=mysqli_stmt_get_result($st);$total=0; ?><!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Checkout | ClassyCubic</title><link rel="stylesheet" href="css/style.css"></head><body><?php include __DIR__.'/includes/navbar.php'; ?><div class="page-wrap"><h2>Checkout</h2><?php if(mysqli_num_rows($res)===0): ?><div class="alert-box info">Your cart is empty. <a href="shop.php">Continue shopping</a></div><?php else: ?><div class="checkout-grid"><div class="summary-box"><h3>Order Summary</h3><?php while($i=mysqli_fetch_assoc($res)): $sub=$i['price']*$i['quantity'];$total+=$sub; ?><p><?php echo htmlspecialchars($i['name']); ?> × <?php echo (int)$i['quantity']; ?> — <b>৳<?php echo number_format($sub,2); ?></b></p><?php endwhile; ?><hr><h3>Total: ৳<?php echo number_format($total,2); ?></h3></div><div class="form-card" style="margin:0;max-width:none"><form method="POST" action="place_order.php"><label>Shipping Address</label><textarea name="shipping_address" required></textarea><label>Payment Method</label><select name="payment_method" required><option>Cash on Delivery</option><option>bKash</option><option>Nagad</option><option>Card Payment</option></select><button type="submit">Place Order</button></form></div></div><?php endif; ?></div><footer><p>© 2026 ClassyCubic</p></footer></body></html>